/// One mask component → our component JSON; `Err(kind)` names an unsupported one.
fn component(m: &XmpValue, aspect: f64) -> Result<Value, String> {
    let what = text(m, "crs:What").unwrap_or("");
    let op = match num(m, "crs:MaskBlendMode").unwrap_or(0.0) as i64 {
        1 => "subtract",
        2 => "intersect",
        _ => "add",
    };
    let invert = flag(m, "crs:MaskInverted").unwrap_or(false);
    // positions are fractions of the image's width / height; our radii are in long-edge units
    let (sx, sy) = if aspect >= 1.0 { (1.0, 1.0 / aspect) } else { (aspect, 1.0) };
    let shape = match what {
        "Mask/Gradient" => {
            let g = |k: &str, d: f64| num(m, &format!("crs:{k}")).unwrap_or(d);
            json!({"kind": "linear", "start": pt(g("FullX", 0.5), g("FullY", 0.0)), "end": pt(g("ZeroX", 0.5), g("ZeroY", 1.0))})
        }
        "Mask/CircularGradient" => {
            let g = |k: &str, d: f64| num(m, &format!("crs:{k}")).unwrap_or(d);
            let (l, r, t, b) = (g("Left", 0.25), g("Right", 0.75), g("Top", 0.25), g("Bottom", 0.75));
            json!({
                "kind": "radial",
                "center": pt((l + r) / 2.0, (t + b) / 2.0),
                "rx": ((r - l).abs() / 2.0 * sx).max(1e-3),
                "ry": ((b - t).abs() / 2.0 * sy).max(1e-3),
                "angle": g("Angle", 0.0),
                "feather": g("Feather", 50.0).clamp(0.0, 100.0),
                "invert": flag(m, "crs:Flipped").unwrap_or(false),
            })

/// Strictly re-parses the internal structure of blocks whose data carries
/// its own sizes, so a block that a strict reader would reject is caught
/// here: `PlLd` (a `plcL` placed layer), `SoLd`/`SoLE` (`soLD` placed
/// layer data), `lnk2`/`lnk3`/`lnkD` (length-prefixed linked files) and
/// `lfx2` (object effects). Every inner length must stay inside the block
/// and the parse must end at the end of the data, apart from up to three
/// zero padding bytes. Other keys are not checked and return `Ok`.
///
/// Layouts follow the Adobe Photoshop File Format specification
/// ("Additional Layer Information": Placed Layer, Placed Layer Data,
/// Linked Layer, Object Based Effects Layer Info).
pub fn check_structure(&self) -> Result<()> {
    let d = &self.data[..];
    let mut r = Reader::new(d);
    match &self.key {
        b"PlLd" => {
            expect_kind(&mut r, b"plcL")?;
            let _version = r.u32()?;
            crate::io::read_pascal(&mut r, 1)?;
            // Page, total pages, anti-alias policy, layer type; transform (8 doubles).
            r.skip(4 * 4 + 8 * 8)?;
            let _warp_version = r.u32()?;
            crate::descriptor::VersionedDescriptor::read(&mut r)?;
        }
        b"SoLd" | b"SoLE" => {
            expect_kind(&mut r, b"soLD")?;
            let _version = r.u32()?;
            let d = crate::descriptor::VersionedDescriptor::read(&mut r)?;
            check_placed_descriptor(&d.descriptor).map_err(|e| PsdError::invalid(format!("{}: {e}", self.key_str())))?;
        }
        b"lfx2" => {
            let _effects_version = r.u32()?;
            crate::descriptor::VersionedDescriptor::read(&mut r)?;
        }
        b"lnk2" | b"lnk3" | b"lnkD" => {
            while r.remaining() >= 8 {
                let len = r.u64()?;
                let item = r.bytes_u64(len)?;
                if !matches!(item.get(..4), Some(b"liFD" | b"liFE" | b"liFA")) {
                    return Err(PsdError::invalid(format!("{}: linked item of unknown type", self.key_str())));
                }
                if item.get(..4) == Some(b"liFD") {
                    check_embedded_item(item).map_err(|e| PsdError::invalid(format!("{}: embedded file: {e}", self.key_str())))?;
                }
                // Items are padded to a multiple of 4.
                let pad = ((4 - len % 4) % 4).min(r.remaining() as u64);
                r.skip(pad as usize)?;
            }
        }

/// Layer blending ranges ("Blend If"), stored raw. The data is a sequence of
/// 8-byte entries: composite gray first, then one per channel; each entry is
/// source (black lo, black hi, white lo, white hi) then destination.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct BlendingRanges {
    /// Raw bytes.
    pub data: Vec<u8>,
}

/// One blending range entry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BlendRange {
    /// Source range: black low, black high, white low, white high.
    pub source: [u8; 4],
    /// Destination range.
    pub dest: [u8; 4],
}

impl BlendingRanges {
    /// Default "full" ranges for composite + `channels` channels.
    pub fn full(channels: usize) -> Self {
        let mut data = Vec::with_capacity((channels + 1) * 8);
        for _ in 0..=channels {
            data.extend_from_slice(&[0, 0, 255, 255, 0, 0, 255, 255]);
        }
        BlendingRanges { data }
    }
    /// Parsed entries (incomplete trailing bytes are ignored).
    pub fn ranges(&self) -> Vec<BlendRange> {
        self.data.as_chunks::<8>().0.iter().map(|c| BlendRange { source: [c[0], c[1], c[2], c[3]], dest: [c[4], c[5], c[6], c[7]] }).collect()

